// SPDX-License-Identifier: MIT

// Deployed at: 0xe76fF183A7d5895f9754C4265e527D8442A0Ae34
pragma solidity ^0.8.20;

import "./ArbVault.sol";

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/* =========================================================
 * Interfaces (top-level)
 * ========================================================= */

interface IUniswapV2RouterLike {
    function swapExactTokensForTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external returns (uint[] memory amounts);
}

interface IV3PoolLike {
    function token0() external view returns (address);
    function token1() external view returns (address);

    function swap(
        address recipient,
        bool zeroForOne,
        int256 amountSpecified,          // exactIn: positive, exactOut: negative
        uint160 sqrtPriceLimitX96,
        bytes calldata data
    ) external returns (int256 amount0, int256 amount1);
}

interface IUniswapV3SwapCallback {
    function uniswapV3SwapCallback(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata data
    ) external;
}

/* =========================================================
 * ArbExecutor
 * ========================================================= */

contract ArbExecutorOld is ArbVault, IUniswapV3SwapCallback {

    using SafeERC20 for IERC20;
    uint256 public constant MAX_LOSS_BPS = 100; // 100 = 1% (basis points)

    // --- V3 callback guard ---
    address private _expectedV3Pool;

    // =========================================================
    // Events (runtime analytics)
    // =========================================================

    event ArbExecuted(
        uint256 indexed blockNumber,
        uint256 blockTimestamp,
        address indexed profitToken,
        uint256 startBalance,
        uint256 endBalance,
        int256 profit,
        uint256 totalGasUsed,
        uint256 stepsCount,
        bool revertIfLoss
    );

    event SwapStepExecuted(
        uint256 indexed index,
        uint8 kind,              // uint8(SwapKind)
        address indexed target,  // router or pool
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOut,
        uint256 gasUsed
    );

    error UNEXPECTED_V3_POOL();
    error NO_ACTIVE_V3_SWAP();

    // =========================================================
    // Errors
    // =========================================================

    error ArbExecutionLoss(ArbSummary summary, SwapLog[] logs);

    error LOSS_EXCEEDS_LIMIT(uint256 loss, uint256 maxAllowed);

    error NO_STEPS();
    error PROFIT_TOKEN_ZERO();
    error TOKEN_ZERO();

    error AMOUNT_IN_ZERO();
    error AMOUNT_OUT_ZERO();
    error AMOUNT_IN_MAX_ZERO();

    error DEADLINE_EXPIRED();

    error PATH_TOO_SHORT();
    error ROUTER_ZERO();
    error POOL_ZERO();
    error TOKEN_NOT_IN_POOL();
    error NOT_FROM_POOL();
    error SLIPPAGE();
    error UNKNOWN_SWAP_KIND();

    // --- auto amountIn only for step #2 exact-in ---
    error SECOND_STEP_AMOUNTIN_ZERO_NOT_ALLOWED();
    error SECOND_STEP_PREV_TOKEN_MISMATCH();
    error SECOND_STEP_PREV_OUT_ZERO();

    // =========================================================
    // Types
    // =========================================================

    enum SwapKind {
        V2_EXACT_IN,
        V3_POOL_EXACT_IN
    }

    struct SwapStep {
        SwapKind kind;

        // V2
        address router;
        address[] path;

        // V3
        address pool;

        // common
        address tokenIn;
        address tokenOut;

        // EXACT IN
        uint256 amountIn;        // if 0 and step index == 1 and exact-in => use prev step amountOut
        uint256 amountOutMin;    // exact-in slippage guard (can be 0)

        // V3
        uint160 sqrtPriceLimitX96;

        uint256 deadline; // 0 => block.timestamp + DEFAULT_DEADLINE_SECONDS
    }

    struct SwapLog {
        uint256 index;

        SwapKind kind;
        address target;

        address tokenIn;
        address tokenOut;

        uint256 amountIn;   // фактически потрачено
        uint256 amountOut;  // фактически получено

        uint256 gasUsed;
    }

    struct ArbSummary {
        uint256 blockNumber;
        uint256 blockTimestamp;

        address profitToken;
        uint256 startBalance;
        uint256 endBalance;

        int256 profit;
        uint256 totalGasUsed;
        uint256 stepsCount;
    }

    // =========================================================
    // Config
    // =========================================================

    uint256 public constant DEFAULT_DEADLINE_SECONDS = 120;

    uint160 internal constant MIN_SQRT_RATIO = 4295128739;
    uint160 internal constant MAX_SQRT_RATIO =
    1461446703485210103287273052203988822378723970342;

    constructor(address initialOwner) ArbVault(initialOwner) {}

    // =========================================================
    // Core
    // =========================================================

    function executeSwaps(
        SwapStep[] calldata steps,
        address profitToken,
        bool revertIfLoss,
        bool emitEvents
    ) external onlyOwner nonReentrant returns (ArbSummary memory summary, SwapLog[] memory logs) {
        if (steps.length == 0) revert NO_STEPS();
        if (profitToken == address(0)) revert PROFIT_TOKEN_ZERO();

        uint256 gasStartTotal = gasleft();

        uint256 startBal = _balanceOf(profitToken);
        logs = new SwapLog[](steps.length);

        // Track previous step actual out + tokenOut
        uint256 prevOut = 0;
        address prevTokenOut = address(0);

        for (uint256 i = 0; i < steps.length; i++) {
            uint256 gasStartStep = gasleft();
            SwapStep calldata s = steps[i];

            if (s.tokenIn == address(0) || s.tokenOut == address(0)) revert TOKEN_ZERO();

            uint256 deadline = (s.deadline == 0)
                ? (block.timestamp + DEFAULT_DEADLINE_SECONDS)
                : s.deadline;
            if (block.timestamp > deadline) revert DEADLINE_EXPIRED();

            // execute
            (uint256 amountOutActual, uint256 spentActual) = _doSwapWithResolution(i, steps, s, prevOut, prevTokenOut, deadline);

            uint256 gasUsedStep = gasStartStep - gasleft();

            address target = _targetOf(s);

            logs[i] = SwapLog({
                index: i,
                kind: s.kind,
                target: target,
                tokenIn: s.tokenIn,
                tokenOut: s.tokenOut,
                amountIn: spentActual,
                amountOut: amountOutActual,
                gasUsed: gasUsedStep
            });

            if (emitEvents) {
                emit SwapStepExecuted(
                    i,
                    uint8(s.kind),
                    target,
                    s.tokenIn,
                    s.tokenOut,
                    spentActual,
                    amountOutActual,
                    gasUsedStep
                );
            }

            // update prev trackers
            prevOut = amountOutActual;
            prevTokenOut = s.tokenOut;
        }

        uint256 endBal = _balanceOf(profitToken);
        int256 profit = int256(endBal) - int256(startBal);

        uint256 totalGasUsed = gasStartTotal - gasleft();

        summary = ArbSummary({
            blockNumber: block.number,
            blockTimestamp: block.timestamp,
            profitToken: profitToken,
            startBalance: startBal,
            endBalance: endBal,
            profit: profit,
            totalGasUsed: totalGasUsed,
            stepsCount: steps.length
        });

        if (profit < 0) {
            if (revertIfLoss) {
                revert ArbExecutionLoss(summary, logs);
            }

            // revertIfLoss == false: allow small loss, but cap it
            if (startBal == 0) {
                // with 0 start balance, any "loss" doesn't make sense -> revert to be safe
                revert LOSS_EXCEEDS_LIMIT(0, 0);
            }

            uint256 loss = startBal - endBal; // safe because profit<0 => endBal < startBal
            uint256 maxAllowedLoss = (startBal * MAX_LOSS_BPS) / 10_000;

            if (loss > maxAllowedLoss) {
                revert LOSS_EXCEEDS_LIMIT(loss, maxAllowedLoss);
            }
        }

        if (emitEvents) {
            emit ArbExecuted(
                block.number,
                block.timestamp,
                profitToken,
                startBal,
                endBal,
                profit,
                totalGasUsed,
                steps.length,
                revertIfLoss
            );
        }

        return (summary, logs);
    }

    function _targetOf(SwapStep calldata s) internal pure returns (address) {
        if (s.kind == SwapKind.V2_EXACT_IN) return s.router;
        return s.pool;
    }

    // =========================================================
    // Swap handlers
    // =========================================================

    function _doSwapWithResolution(
        uint256 i,
        SwapStep[] calldata /*steps*/,
        SwapStep calldata s,
        uint256 prevOut,
        address prevTokenOut,
        uint256 deadline
    ) internal returns (uint256 amountOutActual, uint256 spentActual) {
        // -------- EXACT IN kinds (allow auto amountIn on step #2) --------
        if (s.kind == SwapKind.V2_EXACT_IN || s.kind == SwapKind.V3_POOL_EXACT_IN) {
            uint256 amountInResolved = s.amountIn;

            if (amountInResolved == 0) {
                if (i == 1) {
                    if (prevTokenOut != s.tokenIn) revert SECOND_STEP_PREV_TOKEN_MISMATCH();
                    if (prevOut == 0) revert SECOND_STEP_PREV_OUT_ZERO();
                    amountInResolved = prevOut;
                } else {
                    if (i == 0) revert AMOUNT_IN_ZERO();
                    revert SECOND_STEP_AMOUNTIN_ZERO_NOT_ALLOWED();
                }
            }
            if (amountInResolved == 0) revert AMOUNT_IN_ZERO();

            return _doSwapExactIn(s, amountInResolved, deadline);
        }

        revert UNKNOWN_SWAP_KIND();
    }

    function _doSwapExactIn(
        SwapStep calldata s,
        uint256 amountInResolved,
        uint256 deadline
    ) internal returns (uint256 amountOutActual, uint256 spentActual) {
        if (s.kind == SwapKind.V2_EXACT_IN) {
            if (s.router == address(0)) revert ROUTER_ZERO();

            address[] memory path = (s.path.length >= 2)
                ? s.path
                : _defaultPath(s.tokenIn, s.tokenOut);
            if (path.length < 2) revert PATH_TOO_SHORT();

            // ✅ safety: path must match tokens
            if (path[0] != s.tokenIn || path[path.length - 1] != s.tokenOut) revert TOKEN_NOT_IN_POOL();

            _ensureAllowance(s.tokenIn, s.router, amountInResolved);

            uint[] memory amounts = IUniswapV2RouterLike(s.router).swapExactTokensForTokens(
                amountInResolved,
                s.amountOutMin, // can be 0
                path,
                address(this),
                deadline
            );

            spentActual = amounts[0];
            amountOutActual = amounts[amounts.length - 1];
            return (amountOutActual, spentActual);
        }

        if (s.kind == SwapKind.V3_POOL_EXACT_IN) {
            if (s.pool == address(0)) revert POOL_ZERO();

            (amountOutActual, spentActual) = _v3SwapExactInByPool(
                s.pool,
                s.tokenIn,
                s.tokenOut,
                amountInResolved,
                s.amountOutMin,
                s.sqrtPriceLimitX96
            );
            return (amountOutActual, spentActual);
        }

        revert UNKNOWN_SWAP_KIND();
    }

    // =========================================================
    // V3 swaps
    // =========================================================

    function _v3SwapExactInByPool(
        address pool,
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOutMin,
        uint160 sqrtPriceLimitX96
    ) internal returns (uint256 amountOut, uint256 spent) {
        address t0 = IV3PoolLike(pool).token0();
        address t1 = IV3PoolLike(pool).token1();

        bool inIsT0 = (tokenIn == t0);
        bool inIsT1 = (tokenIn == t1);
        bool outIsT0 = (tokenOut == t0);
        bool outIsT1 = (tokenOut == t1);

        if (!((inIsT0 && outIsT1) || (inIsT1 && outIsT0))) revert TOKEN_NOT_IN_POOL();

        bool zeroForOne = inIsT0;

        uint160 limit = sqrtPriceLimitX96;
        if (limit == 0) {
            limit = zeroForOne ? (MIN_SQRT_RATIO + 1) : (MAX_SQRT_RATIO - 1);
        }

        // ✅ set expected pool BEFORE calling swap
        _expectedV3Pool = pool;

        // data: pool, tokenIn, amountInMax(0), enforceMax(false)
        bytes memory data = abi.encode(pool, tokenIn, uint256(0), false);

        (int256 amount0, int256 amount1) = IV3PoolLike(pool).swap(
            address(this),
            zeroForOne,
            int256(amountIn), // exact input
            limit,
            data
        );

        _expectedV3Pool = address(0);

        // ✅ correct delta handling:
        // exactIn: input delta positive, output delta negative
        if (zeroForOne) {
            // token0 in (amount0 > 0), token1 out (amount1 < 0)
            spent = uint256(amount0);
            amountOut = uint256(-amount1);
        } else {
            // token1 in (amount1 > 0), token0 out (amount0 < 0)
            spent = uint256(amount1);
            amountOut = uint256(-amount0);
        }

        if (amountOut < amountOutMin) revert SLIPPAGE();
        return (amountOut, spent);
    }

    // =========================================================
    // V3 callback: pay pool
    // =========================================================

    function uniswapV3SwapCallback(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata data
    ) external override {
        // ✅ must be inside active swap
        if (_expectedV3Pool == address(0)) revert NO_ACTIVE_V3_SWAP();

        // ✅ caller must be exactly the pool we are swapping with
        if (msg.sender != _expectedV3Pool) revert UNEXPECTED_V3_POOL();

        (address pool, address tokenIn, uint256 amountInMax, bool enforceMax) =
                            abi.decode(data, (address, address, uint256, bool));

        // ✅ optional: enforce decoded pool equals msg.sender (доп. защита)
        if (pool != msg.sender) revert UNEXPECTED_V3_POOL();


        // amount{0,1}Delta > 0 => we owe that token to the pool
        if (amount0Delta > 0) {
            address t0 = IV3PoolLike(pool).token0();
            if (tokenIn != t0) revert TOKEN_NOT_IN_POOL();

            uint256 pay = uint256(amount0Delta);
            if (enforceMax && pay > amountInMax) revert SLIPPAGE();

            IERC20(t0).safeTransfer(pool, pay);
            return;
        }

        if (amount1Delta > 0) {
            address t1 = IV3PoolLike(pool).token1();
            if (tokenIn != t1) revert TOKEN_NOT_IN_POOL();

            uint256 pay = uint256(amount1Delta);
            if (enforceMax && pay > amountInMax) revert SLIPPAGE();

            IERC20(t1).safeTransfer(pool, pay);
            return;
        }

        // nothing owed
    }

    // =========================================================
    // Utils
    // =========================================================

    function _defaultPath(address tokenIn, address tokenOut)
    internal
    pure
    returns (address[] memory path)
    {
        path = new address[](2);
        path[0] = tokenIn;
        path[1] = tokenOut;
    }

    function _balanceOf(address token) internal view returns (uint256) {
        return IERC20(token).balanceOf(address(this));
    }

    function _ensureAllowance(address token, address spender, uint256 needed) internal {
        IERC20 erc = IERC20(token);
        uint256 allowance = erc.allowance(address(this), spender);
        if (allowance < needed) {
            erc.forceApprove(spender, type(uint256).max);
        }
    }
}

contracts/ArbQuoteRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";

/* =========================================================
 * Store interface (route config)
 * ========================================================= */
interface ISwapStepsConfigStore {
    struct SwapStep {
        uint8 kind;

        // V2
        address router;
        address[] path; // must be length 0 or 2

        // V3/Algebra
        address pool;

        // common
        address tokenIn;
        address tokenOut;
    }

    function getConfig(bytes32 key) external view returns (SwapStep[] memory);
    function getAllKeys() external view returns (bytes32[] memory);
}

/* =========================================================
 * ArbExecutor interface (simulateSwaps always reverts Simulated)
 * ========================================================= */
interface IArbExecutor {
    struct SwapStep {
        uint8 kind;

        // V2
        address router;
        address[] path;

        // V3
        address pool;

        // common
        address tokenIn;
        address tokenOut;

        // runtime
        uint256 amountIn;
        uint256 amountOutMin;
        uint160 sqrtPriceLimitX96;
        uint256 deadline;
    }

    struct SwapLog {
        uint256 index;
        uint8 kind;
        address target;

        address tokenIn;
        address tokenOut;

        uint256 amountIn;
        uint256 amountOut;

        uint256 gasUsed;
    }

    struct ArbSummary {
        uint256 blockNumber;
        uint256 blockTimestamp;

        address profitToken;
        uint256 startBalance;
        uint256 endBalance;

        int256 profit;
        uint256 totalGasUsed;
        uint256 stepsCount;
    }

    error Simulated(ArbSummary summary, SwapLog[] logs);

    function simulateSwaps(
        SwapStep[] calldata steps,
        address profitToken,
        bool revertIfLoss
    ) external;
}

/* =========================================================
 * ArbQuoteRouter
 * ========================================================= */
contract ArbQuoteRouter is Ownable {
    ISwapStepsConfigStore private _store;
    IArbExecutor private _executor;

    event StoreUpdated(address indexed newStore);
    event ExecutorUpdated(address indexed newExecutor);

    error ZERO_ADDRESS();
    error STORE_NOT_SET();
    error EXECUTOR_NOT_SET();
    error EMPTY_CONFIG();
    error BAD_PATH_LEN(uint256 len);
    error NOT_SIMULATED_REVERT(bytes data);

    constructor(address initialOwner) Ownable(initialOwner) {}

    // =========================
    // setters (owner-only)
    // =========================
    function setStore(address newStore) external onlyOwner {
        if (newStore == address(0)) revert ZERO_ADDRESS();
        _store = ISwapStepsConfigStore(newStore);
        emit StoreUpdated(newStore);
    }

    function setExecutor(address newExecutor) external onlyOwner {
        if (newExecutor == address(0)) revert ZERO_ADDRESS();
        _executor = IArbExecutor(newExecutor);
        emit ExecutorUpdated(newExecutor);
    }

    // =========================
    // getters (addresses)
    // =========================
    function getStore() external view returns (address) {
        return address(_store);
    }

    function getExecutor() external view returns (address) {
        return address(_executor);
    }

    // =========================================================
    // Quote ONE key: returns last amountOut from logs
    // =========================================================
    function quoteByKeyExactIn(
        bytes32 key,
        uint256 amountIn,
        address profitToken,
        bool revertIfLoss
    ) external returns (uint256 amountOutLast) {
        if (address(_store) == address(0)) revert STORE_NOT_SET();
        if (address(_executor) == address(0)) revert EXECUTOR_NOT_SET();

        IArbExecutor.SwapStep[] memory steps = _buildSteps(key, amountIn);

        try _executor.simulateSwaps(steps, profitToken, revertIfLoss) {
            // simulateSwaps должен always revert Simulated(...)
            revert NOT_SIMULATED_REVERT("");
        } catch (bytes memory data) {
            amountOutLast = _decodeLastAmountOutFromSimulated(data);
        }
    }

    // =========================================================
    // Quote ALL keys: returns last amountOut per key
    // =========================================================
    function quoteAllKeysExactIn(
        uint256 amountIn,
        address profitToken,
        bool revertIfLoss
    ) external returns (bytes32[] memory keys, uint256[] memory amountOutLastList) {
        if (address(_store) == address(0)) revert STORE_NOT_SET();
        if (address(_executor) == address(0)) revert EXECUTOR_NOT_SET();

        keys = _store.getAllKeys();
        uint256 n = keys.length;

        amountOutLastList = new uint256[](n);

        for (uint256 k = 0; k < n; k++) {
            IArbExecutor.SwapStep[] memory steps = _buildSteps(keys[k], amountIn);

            try _executor.simulateSwaps(steps, profitToken, revertIfLoss) {
                revert NOT_SIMULATED_REVERT("");
            } catch (bytes memory data) {
                amountOutLastList[k] = _decodeLastAmountOutFromSimulated(data);
            }
        }
    }

    // =========================================================
    // Build runtime steps for ArbExecutor
    // =========================================================
    function _buildSteps(bytes32 key, uint256 amountIn)
    internal
    view
    returns (IArbExecutor.SwapStep[] memory steps)
    {
        ISwapStepsConfigStore.SwapStep[] memory cfg = _store.getConfig(key);
        uint256 n = cfg.length;
        if (n == 0) revert EMPTY_CONFIG();

        steps = new IArbExecutor.SwapStep[](n);

        for (uint256 i = 0; i < n; i++) {
            steps[i].kind = cfg[i].kind;
            steps[i].router = cfg[i].router;
            steps[i].pool = cfg[i].pool;
            steps[i].tokenIn = cfg[i].tokenIn;
            steps[i].tokenOut = cfg[i].tokenOut;

            // ✅ deep-copy path (0 or 2)
            uint256 pl = cfg[i].path.length;
            if (pl == 2) {
                address[] memory p = new address[](2);
                p[0] = cfg[i].path[0];
                p[1] = cfg[i].path[1];
                steps[i].path = p;
            } else if (pl == 0) {
                steps;
            } else {
                revert BAD_PATH_LEN(pl);
            }

            // runtime fields
            steps[i].amountIn = (i == 0) ? amountIn : 0;
            steps[i].amountOutMin = 0;
            steps[i].sqrtPriceLimitX96 = 0;
            steps[i].deadline = 0;
        }
    }

    // =========================================================
    // Decode revert data of Simulated(summary, logs)
    // Return last logs[].amountOut
    // =========================================================
    function _decodeLastAmountOutFromSimulated(bytes memory data)
    internal
    pure
    returns (uint256 lastAmountOut)
    {
        if (data.length < 4) revert NOT_SIMULATED_REVERT(data);

        bytes4 sel;
        assembly {
            sel := mload(add(data, 32))
        }

        if (sel != IArbExecutor.Simulated.selector) {
            revert NOT_SIMULATED_REVERT(data);
        }

        bytes memory payload = _slice(data, 4, data.length - 4);
        (, IArbExecutor.SwapLog[] memory logs) =
                            abi.decode(payload, (IArbExecutor.ArbSummary, IArbExecutor.SwapLog[]));

        if (logs.length == 0) return 0;
        return logs[logs.length - 1].amountOut;
    }

    function _slice(bytes memory data, uint256 start, uint256 len)
    internal
    pure
    returns (bytes memory out)
    {
        out = new bytes(len);
        for (uint256 i = 0; i < len; i++) {
            out[i] = data[start + i];
        }
    }
}

contracts/ArbVault.sol.content:
// SPDX-License-Identifier: MIT

//Deployed at: 0xC211C731f99F86922c4aC5b9625F6357B2b10010
//Owner: 0x90F0fE019Dd68e4bF4dacA998f00C758F7DF4ADE

pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * ArbVault (v1)
 * - Хранит ERC20 токены на контракте
 * - Хранит ETH (native coin Arbitrum) на контракте
 * - Owner может регистрировать токены для отображения (tracked list)
 * - Депозит токенов через transferFrom (нужен approve)
 * - Депозит ETH через receive() / depositETH()
 * - Вывод токенов/ETH owner'ом
 */
contract ArbVault is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ---- tracking ----
    address[] private _trackedTokens;
    mapping(address => bool) public isTrackedToken;

    // ---- events ----
    event TokenRegistered(address indexed token);
    event TokenDeposited(address indexed token, address indexed from, uint256 amount);
    event TokenWithdrawn(address indexed token, address indexed to, uint256 amount);

    event ETHDeposited(address indexed from, uint256 amount);
    event ETHWithdrawn(address indexed to, uint256 amount);

    constructor(address initialOwner) Ownable(initialOwner) {}

    // ======================================================================
    // ETH: RECEIVE / VIEW / DEPOSIT / WITHDRAW
    // ======================================================================

    /// @notice Запрет на принятие ETH обычным переводом на адрес контракта
    receive() external payable {
        revert("ETH_DISABLED_USE_WETH");
    }

    /// @notice (опционально) Явный депозит ETH вызовом функции
    function depositETH() external payable {
        revert("ETH_DISABLED_USE_WETH");
    }

    function ethBalance() external onlyOwner view returns (uint256) {
        return address(this).balance;
    }

    function withdrawETH(address payable to, uint256 amount)
    external
    onlyOwner
    nonReentrant
    {
        require(to != address(0), "TO_ZERO_ADDRESS");
        require(amount > 0, "AMOUNT_ZERO");
        require(address(this).balance >= amount, "INSUFFICIENT_ETH");

        (bool ok, ) = to.call{value: amount}("");
        require(ok, "ETH_TRANSFER_FAILED");

        emit ETHWithdrawn(to, amount);
    }

    function withdrawAllETH(address payable to)
    external
    onlyOwner
    nonReentrant
    returns (uint256 amount)
    {
        require(to != address(0), "TO_ZERO_ADDRESS");

        amount = address(this).balance;
        if (amount > 0) {
            (bool ok, ) = to.call{value: amount}("");
            require(ok, "ETH_TRANSFER_FAILED");

            emit ETHWithdrawn(to, amount);
        }
    }

    // ======================================================================
    // REGISTER / VIEW
    // ======================================================================

    function registerToken(address token) external onlyOwner {
        require(token != address(0), "TOKEN_ZERO_ADDRESS");
        require(!isTrackedToken[token], "TOKEN_ALREADY_TRACKED");

        isTrackedToken[token] = true;
        _trackedTokens.push(token);

        emit TokenRegistered(token);
    }

    function trackedTokens() external onlyOwner view returns (address[] memory) {
        return _trackedTokens;
    }

    function trackedTokenBalances()
    external
    onlyOwner
    view
    returns (address[] memory tokens, uint256[] memory balances)
    {
        uint256 n = _trackedTokens.length;
        tokens = new address[](n);
        balances = new uint256[](n);

        for (uint256 i = 0; i < n; i++) {
            address t = _trackedTokens[i];
            tokens[i] = t;
            balances[i] = IERC20(t).balanceOf(address(this));
        }
    }

    function tokenBalance(address token) external onlyOwner view returns (uint256) {
        require(token != address(0), "TOKEN_ZERO_ADDRESS");
        return IERC20(token).balanceOf(address(this));
    }

    // ======================================================================
    // DEPOSIT
    // ======================================================================

    function depositToken(address token, uint256 amount) external onlyOwner nonReentrant {
        require(token != address(0), "TOKEN_ZERO_ADDRESS");
        require(amount > 0, "AMOUNT_ZERO");

        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);
        emit TokenDeposited(token, msg.sender, amount);
    }

    // ======================================================================
    // WITHDRAW (OWNER)
    // ======================================================================

    function withdrawToken(address token, address to, uint256 amount)
    external
    onlyOwner
    nonReentrant
    {
        require(token != address(0), "TOKEN_ZERO_ADDRESS");
        require(to != address(0), "TO_ZERO_ADDRESS");
        require(amount > 0, "AMOUNT_ZERO");

        IERC20(token).safeTransfer(to, amount);
        emit TokenWithdrawn(token, to, amount);
    }

    function withdrawAllOfToken(address token, address to)
    external
    onlyOwner
    nonReentrant
    returns (uint256 amount)
    {
        require(token != address(0), "TOKEN_ZERO_ADDRESS");
        require(to != address(0), "TO_ZERO_ADDRESS");

        amount = IERC20(token).balanceOf(address(this));
        if (amount > 0) {
            IERC20(token).safeTransfer(to, amount);
            emit TokenWithdrawn(token, to, amount);
        }
    }

    function withdrawAllTrackedTokens(address to)
    external
    onlyOwner
    nonReentrant
    returns (address[] memory tokens, uint256[] memory amounts)
    {
        require(to != address(0), "TO_ZERO_ADDRESS");

        uint256 n = _trackedTokens.length;
        tokens = new address[](n);
        amounts = new uint256[](n);

        for (uint256 i = 0; i < n; i++) {
            address t = _trackedTokens[i];
            tokens[i] = t;

            uint256 bal = IERC20(t).balanceOf(address(this));
            amounts[i] = bal;

            if (bal > 0) {
                IERC20(t).safeTransfer(to, bal);
                emit TokenWithdrawn(t, to, bal);
            }
        }
    }
}

contracts/OwnerMulticall.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

// Deployed at: 0x3E506CDa6Bb473A58a11fED3C1e592E4eE33CcB6

/// @notice Owner-only multicall, aggregate3-like.
/// @dev Intended to be called via eth_call (staticCall in ethers) for simulations.
contract OwnerMulticall {
    error NOT_OWNER(address caller);
    error CALL_FAILED(uint256 index, address target);
    error TOO_MANY_CALLS(uint256 calls, uint256 maxCalls);

    address public immutable owner;
    uint256 public immutable maxCalls; // 0 => unlimited

    constructor(address _owner, uint256 _maxCalls) {
        owner = _owner;
        maxCalls = _maxCalls;
    }

    modifier onlyOwner() {
        if (msg.sender != owner) revert NOT_OWNER(msg.sender);
        _;
    }

    struct Call3 {
        address target;
        bool allowFailure;
        bytes callData;
    }

    struct Result {
        bool success;
        bytes returnData;
    }

    /// @notice aggregate3 аналог. Делает обычный call к target'ам.
    /// @dev Если allowFailure=false и call упал — ревертит весь aggregate3.
    function aggregate3(Call3[] calldata calls)
    external
    onlyOwner
    returns (Result[] memory results)
    {
        uint256 n = calls.length;
        uint256 limit = maxCalls;
        if (limit != 0 && n > limit) revert TOO_MANY_CALLS(n, limit);

        results = new Result[](n);

        for (uint256 i = 0; i < n; i++) {
            Call3 calldata c = calls[i];

            // обычный call (НЕ staticcall), чтобы можно было симулировать swap-цепочки в eth_call
            (bool ok, bytes memory ret) = c.target.call(c.callData);

            if (!ok && !c.allowFailure) revert CALL_FAILED(i, c.target);

            results[i] = Result({ success: ok, returnData: ret });
        }
    }
}

contracts/SwapStepsConfigReader.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./SwapStepsConfigStore.sol";
import "./ArbExecutor.sol";

/* =========================================================
 * Interface for ArbExecutor.simulateSwaps (always reverts)
 * ========================================================= */
interface IArbExecutorSim {
    struct SwapStep {
        uint8 kind;
        address router;
        address[] path;
        address pool;
        address tokenIn;
        address tokenOut;
        uint256 amountIn;
        uint256 amountOutMin;
        uint160 sqrtPriceLimitX96;
        uint256 deadline;
    }

    struct SwapLog {
        uint256 index;
        uint8 kind;
        address target;
        address tokenIn;
        address tokenOut;
        uint256 amountIn;
        uint256 amountOut;
        uint256 gasUsed;
    }

    struct ArbSummary {
        uint256 blockNumber;
        uint256 blockTimestamp;
        address profitToken;
        uint256 startBalance;
        uint256 endBalance;
        int256 profit;
        uint256 totalGasUsed;
        uint256 stepsCount;
    }

    error Simulated(ArbSummary summary, SwapLog[] logs);

    function simulateSwaps(
        SwapStep[] calldata steps,
        address profitToken,
        bool revertIfLoss
    ) external;
}

contract SwapStepsConfigReader {
    SwapStepsConfigStore public immutable configStore;
    IArbExecutorSim public immutable executor;

    error ZERO_ADDRESS();

    // =========================================================
    // Structs — buildExecutorSteps
    // =========================================================

    struct StepGroup {
        address tokenIn;
        address tokenOut;
        ArbExecutor.SwapStep[] steps;
    }

    struct GroupedBuildResult {
        StepGroup[] groups;
        uint256 blockNumber;
        uint256 gasUsed;
    }

    // =========================================================
    // Structs — findArb
    // =========================================================

    /// @notice Result of sell-back simulation for one pool in a group.
    struct SellQuote {
        uint256 sellPoolIndex;   // index within the group
        int256  profit;          // finalWETH - amountIn (negative = loss)
        uint256 buyAmountOut;    // amountOut of the buy step
        uint256 sellAmountOut;   // amountOut of the sell step (= final WETH)
        uint256 gasUsed;         // total gas of 2-step simulation
        bool    success;         // false if simulation reverted unexpectedly
    }

    /// @notice Arb analysis for one (tokenIn, tokenOut) group.
    struct GroupArbResult {
        address tokenIn;
        address tokenOut;
        uint256 poolCount;        // total pools in this group
        uint256 bestBuyIndex;     // index of pool with best buy price within group
        uint256 bestBuyAmountOut; // amountOut of best buy pool
        SellQuote[] sells;        // one entry per pool (sell-back via each pool)
        bool    hasProfitable;    // true if at least one sell is profitable
    }

    /// @notice Full arb scan result.
    struct ArbScanResult {
        GroupArbResult[] groups;
        uint256 blockNumber;
        uint256 gasUsed;
    }

    // =========================================================
    // Constructor
    // =========================================================

    constructor(address _configStore, address _executor) {
        if (_configStore == address(0)) revert ZERO_ADDRESS();
        if (_executor == address(0)) revert ZERO_ADDRESS();
        configStore = SwapStepsConfigStore(_configStore);
        executor = IArbExecutorSim(_executor);
    }

    // =========================================================
    // getConfig (unchanged)
    // =========================================================

    function getConfig(bytes32 key)
        external
        view
        returns (SwapStepsConfigStore.SwapStep[] memory)
    {
        return configStore.getConfig(key);
    }

    // =========================================================
    // buildExecutorSteps (unchanged)
    // =========================================================

    function buildExecutorSteps(
        bytes32 key,
        uint256 amountIn
    ) external view returns (GroupedBuildResult memory result) {
        uint256 gasStart = gasleft();

        SwapStepsConfigStore.SwapStep[] memory raw = configStore.getConfig(key);
        result.groups = _groupSteps(raw, amountIn);
        result.blockNumber = block.number;
        result.gasUsed = gasStart - gasleft();
    }

    // =========================================================
    // findArb — main entry point
    // =========================================================

    /// @notice Analyse all pools under `key` for arbitrage opportunities.
    ///         Must be called via staticCall (simulateSwaps mutates state then reverts).
    ///
    /// Algorithm:
    ///   1. Get raw configs from store by key
    ///   2. Build one SwapStep per pool with amountIn, simulate each individually
    ///   3. Group results by (tokenIn,tokenOut), find best buy price per group
    ///   4. For each group: simulate 2-step arb (buy in best pool → sell-back in each pool)
    ///   5. Return grouped report with profit info
    function findArb(
        bytes32 key,
        uint256 amountIn,
        address profitToken
    ) external returns (ArbScanResult memory result) {
        uint256 gasStart = gasleft();

        // Step 1: get raw configs
        SwapStepsConfigStore.SwapStep[] memory raw = configStore.getConfig(key);

        // Step 2: build sim steps and simulate each pool individually
        //         For buy-only simulation, use tokenOut as profitToken so executor
        //         doesn't revert with LOSS_EXCEEDS_LIMIT (we spend profitToken, not gain it)
        IArbExecutorSim.SwapStep[] memory allSteps = _toSimSteps(raw, amountIn);
        uint256 n = allSteps.length;

        uint256[] memory amountsOut = new uint256[](n);
        bool[] memory buyOk = new bool[](n);
        for (uint256 i = 0; i < n; i++) {
            IArbExecutorSim.SwapStep[] memory single = new IArbExecutorSim.SwapStep[](1);
            single[0] = allSteps[i];
            // Use tokenOut as profitToken for buy-only simulation
            address buyProfitToken = allSteps[i].tokenOut;
            (bool ok, uint256 amtOut,) = _simulate(single, buyProfitToken);
            amountsOut[i] = amtOut;
            buyOk[i] = ok;
        }

        // Steps 3-6: group, find best buy, simulate arb, build report
        result.groups = _buildArbReport(raw, allSteps, amountsOut, buyOk, profitToken);
        result.blockNumber = block.number;
        result.gasUsed = gasStart - gasleft();
    }

    // =========================================================
    // Fast path: 2-call flow for bots (1 RPC each)
    // =========================================================

    /// @notice Результат buy-квоты для одного пула.
    struct BuyQuote {
        uint256 index;       // index in raw config array
        address tokenIn;
        address tokenOut;
        uint256 amountOut;   // 0 if failed
        bool    success;
    }

    /// @notice Результат quoteBuys.
    struct BuyQuotesResult {
        BuyQuote[] quotes;
        uint256 blockNumber;
        uint256 gasUsed;
    }

    /// @notice Этап 1: симулирует buy для каждого пула по ключу.
    ///         Один staticCall → все buy-квоты.
    ///         Бот затем off-chain группирует и находит bestBuyIndex.
    function quoteBuys(
        bytes32 key,
        uint256 amountIn
    ) external returns (BuyQuotesResult memory result) {
        uint256 gasStart = gasleft();

        SwapStepsConfigStore.SwapStep[] memory raw = configStore.getConfig(key);
        IArbExecutorSim.SwapStep[] memory allSteps = _toSimSteps(raw, amountIn);
        uint256 n = allSteps.length;

        result.quotes = new BuyQuote[](n);

        for (uint256 i = 0; i < n; i++) {
            IArbExecutorSim.SwapStep[] memory single = new IArbExecutorSim.SwapStep[](1);
            single[0] = allSteps[i];
            address buyProfitToken = allSteps[i].tokenOut;
            (bool ok, uint256 amtOut,) = _simulate(single, buyProfitToken);

            result.quotes[i] = BuyQuote({
                index: i,
                tokenIn: allSteps[i].tokenIn,
                tokenOut: allSteps[i].tokenOut,
                amountOut: amtOut,
                success: ok
            });
        }

        result.blockNumber = block.number;
        result.gasUsed = gasStart - gasleft();
    }

    /// @notice Пара индексов для arb-симуляции.
    struct ArbPairInput {
        uint256 buyIndex;    // index of buy pool in raw config
        uint256 sellIndex;   // index of sell pool (will be inverted)
    }

    /// @notice Результат arb-симуляции одной пары.
    struct ArbPairResult {
        uint256 buyIndex;
        uint256 sellIndex;
        int256  profit;
        uint256 buyAmountOut;
        uint256 sellAmountOut;
        uint256 gasUsed;
        bool    success;
    }

    /// @notice Результат scanArbPairs.
    struct ArbPairsResult {
        ArbPairResult[] results;
        uint256 blockNumber;
        uint256 gasUsed;
    }

    /// @notice Этап 2: бот передаёт список пар (buyIdx, sellIdx),
    ///         контракт симулирует 2-step arb для каждой.
    ///         Один staticCall → все arb-результаты.
    function scanArbPairs(
        bytes32 key,
        uint256 amountIn,
        address profitToken,
        ArbPairInput[] calldata pairs
    ) external returns (ArbPairsResult memory result) {
        uint256 gasStart = gasleft();

        SwapStepsConfigStore.SwapStep[] memory raw = configStore.getConfig(key);
        IArbExecutorSim.SwapStep[] memory allSteps = _toSimSteps(raw, amountIn);

        uint256 pLen = pairs.length;
        result.results = new ArbPairResult[](pLen);

        for (uint256 i = 0; i < pLen; i++) {
            IArbExecutorSim.SwapStep memory buyStep = allSteps[pairs[i].buyIndex];
            IArbExecutorSim.SwapStep memory sellStep = _invertStep(allSteps[pairs[i].sellIndex]);

            (bool ok, int256 pft, uint256 buyAmtO, uint256 sellAmtO, uint256 gas) =
                _simulateArb(buyStep, sellStep, profitToken);

            result.results[i] = ArbPairResult({
                buyIndex: pairs[i].buyIndex,
                sellIndex: pairs[i].sellIndex,
                profit: pft,
                buyAmountOut: buyAmtO,
                sellAmountOut: sellAmtO,
                gasUsed: gas,
                success: ok
            });
        }

        result.blockNumber = block.number;
        result.gasUsed = gasStart - gasleft();
    }

    // =========================================================
    // Internal — simulation helpers
    // =========================================================

    /// @dev Call executor.simulateSwaps, decode Simulated revert.
    function _simulate(
        IArbExecutorSim.SwapStep[] memory steps,
        address profitToken
    ) internal returns (bool success, uint256 lastAmountOut, uint256 totalGas) {
        try executor.simulateSwaps(steps, profitToken, false) {
            return (false, 0, 0);
        } catch (bytes memory data) {
            return _decodeSimulated(data);
        }
    }

    /// @dev Simulate a 2-step arb: buy in bestPool, sell-back in sellPool.
    function _simulateArb(
        IArbExecutorSim.SwapStep memory buyStep,
        IArbExecutorSim.SwapStep memory sellStep,
        address profitToken
    ) internal returns (bool success, int256 profit, uint256 buyAmtOut, uint256 sellAmtOut, uint256 gasUsed) {
        IArbExecutorSim.SwapStep[] memory pair = new IArbExecutorSim.SwapStep[](2);
        pair[0] = buyStep;
        pair[1] = sellStep;  // amountIn=0 → auto from prevOut

        try executor.simulateSwaps(pair, profitToken, false) {
            return (false, int256(0), 0, 0, 0);
        } catch (bytes memory data) {
            if (data.length < 4) return (false, int256(0), 0, 0, 0);

            bytes4 sel;
            assembly { sel := mload(add(data, 32)) }
            if (sel != IArbExecutorSim.Simulated.selector) return (false, int256(0), 0, 0, 0);

            bytes memory payload = _slice(data, 4, data.length - 4);
            (IArbExecutorSim.ArbSummary memory summary, IArbExecutorSim.SwapLog[] memory logs) =
                abi.decode(payload, (IArbExecutorSim.ArbSummary, IArbExecutorSim.SwapLog[]));

            if (logs.length < 2) return (false, int256(0), 0, 0, 0);

            return (
                true,
                summary.profit,
                logs[0].amountOut,
                logs[1].amountOut,
                summary.totalGasUsed
            );
        }
    }

    /// @dev Decode Simulated revert data → (success, lastAmountOut, totalGasUsed).
    function _decodeSimulated(bytes memory data)
        internal pure returns (bool, uint256, uint256)
    {
        if (data.length < 4) return (false, 0, 0);

        bytes4 sel;
        assembly { sel := mload(add(data, 32)) }
        if (sel != IArbExecutorSim.Simulated.selector) return (false, 0, 0);

        bytes memory payload = _slice(data, 4, data.length - 4);
        (IArbExecutorSim.ArbSummary memory summary, IArbExecutorSim.SwapLog[] memory logs) =
            abi.decode(payload, (IArbExecutorSim.ArbSummary, IArbExecutorSim.SwapLog[]));

        if (logs.length == 0) return (true, 0, summary.totalGasUsed);
        return (true, logs[logs.length - 1].amountOut, summary.totalGasUsed);
    }

    // =========================================================
    // Internal — arb report builder
    // =========================================================

    function _buildArbReport(
        SwapStepsConfigStore.SwapStep[] memory raw,
        IArbExecutorSim.SwapStep[] memory allSteps,
        uint256[] memory amountsOut,
        bool[] memory buyOk,
        address profitToken
    ) internal returns (GroupArbResult[] memory groups) {
        uint256 n = raw.length;

        // --- Phase 1: find unique pairs & best buy per pair ---
        address[] memory uIn  = new address[](n);
        address[] memory uOut = new address[](n);
        uint256[] memory bestIdx    = new uint256[](n);
        uint256[] memory bestAmtOut = new uint256[](n);
        uint256[] memory counts     = new uint256[](n);
        uint256 gc = 0;

        for (uint256 i = 0; i < n; i++) {
            bool found = false;
            for (uint256 g = 0; g < gc; g++) {
                if (uIn[g] == raw[i].tokenIn && uOut[g] == raw[i].tokenOut) {
                    counts[g]++;
                    if (buyOk[i] && amountsOut[i] > bestAmtOut[g]) {
                        bestAmtOut[g] = amountsOut[i];
                        bestIdx[g] = i;
                    }
                    found = true;
                    break;
                }
            }
            if (!found) {
                uIn[gc]  = raw[i].tokenIn;
                uOut[gc] = raw[i].tokenOut;
                counts[gc] = 1;
                bestIdx[gc] = i;
                bestAmtOut[gc] = buyOk[i] ? amountsOut[i] : 0;
                gc++;
            }
        }

        // --- Phase 2: allocate groups & collect member indices ---
        groups = new GroupArbResult[](gc);
        uint256[] memory cursor = new uint256[](gc);
        uint256[][] memory memberIdx = new uint256[][](gc);

        for (uint256 g = 0; g < gc; g++) {
            groups[g].tokenIn  = uIn[g];
            groups[g].tokenOut = uOut[g];
            groups[g].poolCount = counts[g];
            groups[g].bestBuyAmountOut = bestAmtOut[g];
            groups[g].sells = new SellQuote[](counts[g]);
            memberIdx[g] = new uint256[](counts[g]);
        }

        for (uint256 i = 0; i < n; i++) {
            for (uint256 g = 0; g < gc; g++) {
                if (uIn[g] == raw[i].tokenIn && uOut[g] == raw[i].tokenOut) {
                    memberIdx[g][cursor[g]] = i;
                    cursor[g]++;
                    break;
                }
            }
        }

        // --- Phase 3: find bestBuyIndex within group & simulate arbs ---
        for (uint256 g = 0; g < gc; g++) {
            // Find local index of best buy pool
            uint256 localBest = 0;
            for (uint256 j = 0; j < counts[g]; j++) {
                if (memberIdx[g][j] == bestIdx[g]) {
                    localBest = j;
                    break;
                }
            }
            groups[g].bestBuyIndex = localBest;

            // If best buy failed or produced 0, skip arb simulations
            if (bestAmtOut[g] == 0) {
                for (uint256 j = 0; j < counts[g]; j++) {
                    groups[g].sells[j] = SellQuote({
                        sellPoolIndex: j,
                        profit: int256(0),
                        buyAmountOut: 0,
                        sellAmountOut: 0,
                        gasUsed: 0,
                        success: false
                    });
                }
                continue;
            }

            // Build the buy step (best pool in group)
            IArbExecutorSim.SwapStep memory buyStep = allSteps[bestIdx[g]];

            // For each pool: build reversed sell step, simulate 2-step arb
            for (uint256 j = 0; j < counts[g]; j++) {
                uint256 rawIdx = memberIdx[g][j];
                IArbExecutorSim.SwapStep memory sellStep = _invertStep(allSteps[rawIdx]);

                (bool ok, int256 pft, uint256 buyAmtO, uint256 sellAmtO, uint256 gas) =
                    _simulateArb(buyStep, sellStep, profitToken);

                groups[g].sells[j] = SellQuote({
                    sellPoolIndex: j,
                    profit: pft,
                    buyAmountOut: buyAmtO,
                    sellAmountOut: sellAmtO,
                    gasUsed: gas,
                    success: ok
                });

                if (ok && pft > 0) {
                    groups[g].hasProfitable = true;
                }
            }
        }
    }

    // =========================================================
    // Internal — step conversion helpers
    // =========================================================

    /// @dev Convert raw store steps to simulator-ready steps with amountIn.
    function _toSimSteps(
        SwapStepsConfigStore.SwapStep[] memory raw,
        uint256 amountIn
    ) internal pure returns (IArbExecutorSim.SwapStep[] memory steps) {
        uint256 n = raw.length;
        steps = new IArbExecutorSim.SwapStep[](n);

        for (uint256 i = 0; i < n; i++) {
            steps[i] = IArbExecutorSim.SwapStep({
                kind:              raw[i].kind,
                router:            raw[i].router,
                path:              raw[i].path,
                pool:              raw[i].pool,
                tokenIn:           raw[i].tokenIn,
                tokenOut:          raw[i].tokenOut,
                amountIn:          amountIn,
                amountOutMin:      0,
                sqrtPriceLimitX96: 0,
                deadline:          0
            });
        }
    }

    /// @dev Invert a step: swap tokenIn↔tokenOut, reverse path, amountIn=0 (auto from prev).
    function _invertStep(
        IArbExecutorSim.SwapStep memory s
    ) internal pure returns (IArbExecutorSim.SwapStep memory inv) {
        inv.kind              = s.kind;
        inv.router            = s.router;
        inv.pool              = s.pool;
        inv.tokenIn           = s.tokenOut;  // reversed
        inv.tokenOut          = s.tokenIn;   // reversed
        inv.amountIn          = 0;           // auto from previous step output
        inv.amountOutMin      = 0;
        inv.sqrtPriceLimitX96 = 0;
        inv.deadline          = 0;

        // Reverse path for V2
        if (s.path.length == 2) {
            address[] memory revPath = new address[](2);
            revPath[0] = s.path[1];
            revPath[1] = s.path[0];
            inv.path = revPath;
        } else {
            inv.path = new address[](0);
        }
    }

    // =========================================================
    // Internal — groupSteps (for buildExecutorSteps, unchanged)
    // =========================================================

    function _groupSteps(
        SwapStepsConfigStore.SwapStep[] memory raw,
        uint256 amountIn
    ) internal pure returns (StepGroup[] memory groups) {
        uint256 n = raw.length;
        if (n == 0) {
            groups = new StepGroup[](0);
            return groups;
        }

        address[] memory uTokenIn  = new address[](n);
        address[] memory uTokenOut = new address[](n);
        uint256[] memory counts    = new uint256[](n);
        uint256 groupCount = 0;

        for (uint256 i = 0; i < n; i++) {
            bool found = false;
            for (uint256 g = 0; g < groupCount; g++) {
                if (uTokenIn[g] == raw[i].tokenIn && uTokenOut[g] == raw[i].tokenOut) {
                    counts[g]++;
                    found = true;
                    break;
                }
            }
            if (!found) {
                uTokenIn[groupCount]  = raw[i].tokenIn;
                uTokenOut[groupCount] = raw[i].tokenOut;
                counts[groupCount]    = 1;
                groupCount++;
            }
        }

        groups = new StepGroup[](groupCount);
        for (uint256 g = 0; g < groupCount; g++) {
            groups[g].tokenIn  = uTokenIn[g];
            groups[g].tokenOut = uTokenOut[g];
            groups[g].steps    = new ArbExecutor.SwapStep[](counts[g]);
            counts[g] = 0;
        }

        for (uint256 i = 0; i < n; i++) {
            for (uint256 g = 0; g < groupCount; g++) {
                if (uTokenIn[g] == raw[i].tokenIn && uTokenOut[g] == raw[i].tokenOut) {
                    uint256 idx = counts[g]++;
                    groups[g].steps[idx] = ArbExecutor.SwapStep({
                        kind:              ArbExecutor.SwapKind(raw[i].kind),
                        router:            raw[i].router,
                        path:              raw[i].path,
                        pool:              raw[i].pool,
                        tokenIn:           raw[i].tokenIn,
                        tokenOut:          raw[i].tokenOut,
                        amountIn:          amountIn,
                        amountOutMin:      0,
                        sqrtPriceLimitX96: 0,
                        deadline:          0
                    });
                    break;
                }
            }
        }
    }

    // =========================================================
    // Internal — bytes utils
    // =========================================================

    function _slice(bytes memory data, uint256 start, uint256 len)
        internal pure returns (bytes memory out)
    {
        out = new bytes(len);
        for (uint256 i = 0; i < len; i++) {
            out[i] = data[start + i];
        }
    }
}

